<script setup lang="ts">
import {can} from './session'
import ShippingProductPicker from './ShippingProductPicker.vue'
import ShippingPackingEditor from './ShippingPackingEditor.vue'
import ShippingPlanUpload from './ShippingPlanUpload.vue'
const planUploadOpen=ref(false)
import {useTableWidths} from './tableWidths'
const tableWidths=useTableWidths('ShippingPanel')

import {ref,reactive,computed,onMounted,watch} from 'vue'
import {ElMessage,ElMessageBox} from 'element-plus'
import {api,session} from './session'
const emit=defineEmits(['open-sta'])
const props=defineProps<{initialStore:string,active?:boolean,target?:{id:number,request:number}}>();const admin=computed(()=>can('shipping','operate'))
const options=reactive<any>({stores:[],countries:{},channels:{},states:{},warehouses:[]});const rows=ref<any[]>([]),total=ref(0),page=ref(1),pageSize=ref(25),loading=ref(false),error=ref(''),busy=ref(false)
const selected=ref<any[]>([]),counts=ref<Record<string,number>>({})
const stateTabs=[{key:'',label:'全部'},{key:'pending',label:'待装箱'},{key:'packed',label:'已装箱'},{key:'shipping',label:'发货中'},{key:'completed',label:'已完成'}]
const stateLabel:Record<string,string>={pending:'待装箱',packed:'已装箱',shipping:'发货中',completed:'已完成'}
function sourceNumbers(row:any):string[]{return [...new Set<string>((row.source==='remainder'?row.source_refs?.shipping_numbers:row.source==='purchase_plan'?row.source_refs?.plan_numbers:row.source_refs?.order_numbers)||[])]}
const inventoryLabel:Record<string,string>={locked:'已锁定',unlocked:'未锁定',outbound:'已出库'}
const filters=reactive<any>({store:props.initialStore,country:'',channel:'',warehouse_id:'',status:'',q:''})
function uuid(){if(crypto.randomUUID)return crypto.randomUUID();const b=crypto.getRandomValues(new Uint8Array(16));b[6]=(b[6]&15)|64;b[8]=(b[8]&63)|128;const s=Array.from(b,v=>v.toString(16).padStart(2,'0')).join('');return `${s.slice(0,8)}-${s.slice(8,12)}-${s.slice(12,16)}-${s.slice(16,20)}-${s.slice(20)}`}
const dateToday=()=>new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Shanghai'}).format(new Date());const stamp=(s:string)=>new Date(s).toLocaleString('zh-CN',{hour12:false})
let seq=0
async function load(){const n=++seq;loading.value=true;error.value='';try{const d=await api('/shipping?'+new URLSearchParams({...Object.fromEntries(Object.entries(filters).filter(([,v])=>v!==null&&v!==undefined&&v!=='')),page:String(page.value),page_size:String(pageSize.value)}));if(n===seq){rows.value=d.rows;total.value=d.total;counts.value=d.counts||{};selected.value=[]}}catch(e){if(n===seq)error.value=(e as Error).message}finally{if(n===seq)loading.value=false}}
function search(){page.value=1;load()}
const addingProducts=ref(false),originalProducts=ref<number[]>([])
const pickerBusy=ref(false)
const editor=ref(false),editId=ref<number|null>(null),form=reactive<any>({}),dialogError=ref('')
async function choices(i:any){i.candidates=await api('/shipping/candidates?'+new URLSearchParams({store:form.store,country:form.country,product_id:String(i.product_id)}));if(!i.candidates.some((c:any)=>c.id===i.listing_id))i.listing_id=i.candidates.length===1?i.candidates[0].id:null}
async function destinations(){if(!editId.value)return;try{for(const i of form.items)await choices(i)}catch(e){dialogError.value=(e as Error).message}}
async function openEdit(row?:any){if(row&&(row.lock_inventory||row.locked)){ElMessage.warning('请先释放库存再编辑发货计划');return;}editId.value=row?.id||null;dialogError.value='';Object.assign(form,{request_id:uuid(),revision:row?.revision,store:row?.store||filters.store||options.stores[0],country:row?.country||filters.country||'UK',channel:row?.channel||'sea',warehouse_id:row?.warehouse_id||options.warehouses[0]?.id,ship_date:row?.ship_date||dateToday(),note:row?.note||'',discard_packing:false,lock_inventory:false,items:(row?.items||[]).map((i:any)=>({...i,candidates:[]})),packing_id:row?.packing_id,from_purchase:row?.from_purchase});pickerBusy.value=false;addingProducts.value=false;originalProducts.value=(row?.items||[]).map((i:any)=>i.product_id);editor.value=true;await destinations()}
async function save(){if(busy.value||pickerBusy.value)return;dialogError.value='';if(!form.items.length||!form.warehouse_id){dialogError.value='请选择仓库并添加商品';return}busy.value=true;try{const body={...(!editId.value?{lock_inventory:form.lock_inventory}:{}),request_id:form.request_id,revision:form.revision,store:form.store,country:form.country,channel:form.channel,warehouse_id:form.warehouse_id,ship_date:form.ship_date,note:form.note,discard_packing:form.discard_packing,items:form.items.map((i:any)=>({product_id:i.product_id,listing_id:i.listing_id,quantity:i.quantity}))};await api(editId.value?`/shipping/${editId.value}/change`:'/shipping',body);editor.value=false;ElMessage.success('发货计划已保存');await load()}catch(e){dialogError.value=(e as Error).message}finally{busy.value=false}}
const packingEdit=ref<any>(null)
const itemEditor=ref(false),itemError=ref(''),itemForm=reactive<any>({})
function itemBlocked(row:any){return !!(row.lock_inventory||row.locked||row.sta||row.outbound_at)}
function itemHint(row:any){return row.outbound_at?'已出库，不能修改':row.sta?'已关联 STA，请先取消 STA':row.lock_inventory||row.locked?'请先释放库存':''}
function editItem(row:any,item:any,index:number){Object.assign(itemForm,{id:row.id,revision:row.revision,index,quantity:item.quantity,minimum:Math.max(1,item.packed||0),name:item.name,code:item.code});itemError.value='';itemEditor.value=true}
async function saveItem(){if(busy.value)return;busy.value=true;itemError.value='';try{await api(`/shipping/${itemForm.id}/item-change`,{revision:itemForm.revision,index:itemForm.index,quantity:itemForm.quantity});itemEditor.value=false;ElMessage.success('计划数量已更新');await load()}catch(e){itemError.value=(e as Error).message}finally{busy.value=false}}
async function deleteItem(row:any,item:any,index:number){if(busy.value)return;try{await ElMessageBox.confirm(`从 ${row.number} 移除 ${item.code} · ${item.name} 的计划（${item.quantity} 件）？${row.items.length===1?'这是最后一条明细，批次也将删除。':'其他明细保留。'}`,'删除发货计划明细',{type:'warning',confirmButtonText:'删除',cancelButtonText:'取消'});busy.value=true;await api(`/shipping/${row.id}/item-change`,{revision:row.revision,index,quantity:0});ElMessage.success('计划明细已删除');await load()}catch(e){if(e!=='cancel'&&e!=='close')error.value=(e as Error).message}finally{busy.value=false}}
async function editPacking(row:any){try{packingEdit.value=await api(`/shipping/${row.id}/detail`)}catch(e){error.value=(e as Error).message}}
async function inventoryAction(row:any,action:string){if(busy.value)return;try{await ElMessageBox.confirm(`将未装箱的 ${row.remaining} 件创建为新的未锁定发货计划，并从当前计划扣减？`,'创建剩货计划',{type:'warning'});busy.value=true;const result=await api(`/shipping/${row.id}/${action}`,{revision:row.revision,request_id:uuid()});ElMessage.success(`已创建剩货计划 ${result.number}`);await load()}catch(e){if(e instanceof Error){error.value=e.message;ElMessage.error(e.message)}}finally{busy.value=false}}
const inventoryConfirming=ref(false)
const inventoryCommands=[{key:'lock-stock',label:'锁定库存'},{key:'release-stock',label:'释放库存'},{key:'manual-outbound',label:'出库'},{key:'undo-outbound',label:'撤销出库'}]
function inventoryReason(row:any,action:string){
 if(['queued','running','uncertain'].includes(row.sta?.status)||row.sta?.cancelling)return '货件操作尚未结束'
 const outbound=!!row.outbound_at||row.inventory_status==='outbound'
 if(action==='undo-outbound')return outbound?'':'仅已出库计划可撤销出库'
 if(outbound)return '请先撤销出库'
 if(action==='lock-stock')return row.inventory_status==='locked'?'已锁定足额库存':''
 if(action==='release-stock')return row.lock_inventory||row.locked?'':'当前计划没有锁定库存'
 return row.workflow_status==='completed'?'':'仅已完成计划可出库'
}
function inventoryBlocked(action:string){return busy.value||inventoryConfirming.value||loading.value||!selected.value.length||selected.value.some(row=>!!inventoryReason(row,action))}
function inventoryHint(action:string){return selected.value.map(row=>inventoryReason(row,action)).find(Boolean)||''}
async function selectedInventoryAction(action:string){
 if(inventoryBlocked(action))return
 const title=inventoryCommands.find(x=>x.key===action)?.label;if(!title)return
 const tasks=selected.value.map(row=>({id:row.id,revision:row.revision})),numbers=selected.value.map(row=>row.number).join('、')
 const messages:Record<string,string>={'lock-stock':'按计划数量校验并锁定可用库存。','release-stock':'释放选中计划的锁定库存，转为可用量。','manual-outbound':'按实际装箱数量出库；库存不足时不会执行。','undo-outbound':'按原出库流水恢复库存为可用量。'}
 inventoryConfirming.value=true
 try{
  await ElMessageBox.confirm(`${messages[action]}共 ${tasks.length} 个计划：${numbers}。任一计划不符合条件时整批不执行。`,title,{type:'warning',confirmButtonText:`确定${title}`,cancelButtonText:'取消'})
  busy.value=true
  await api('/shipping/inventory-batch',{action,tasks})
  ElMessage.success(`${tasks.length} 个计划${title}成功`);await load()
 }catch(e){if(e instanceof Error){error.value=e.message;ElMessage.error(e.message);await load();error.value=e.message}}
 finally{busy.value=false;inventoryConfirming.value=false}
}
function hasOriginalPlan(row:any){return row.original_quantity!=null&&row.original_quantity!==row.quantity}
async function remove(row:any){try{await ElMessageBox.confirm(`删除 ${row.number}？将释放该批次锁定库存，来源采购单的对应数量可再次生成计划。装箱历史保留。`,'删除发货计划',{type:'warning'});await api(`/shipping/${row.id}/delete`,{revision:row.revision});await load()}catch(e){if(e!=='cancel'&&e!=='close')error.value=(e as Error).message}}
async function download(path:string,name:string,body?:any){const r=await fetch('/api'+path,{method:body?'POST':'GET',headers:body?{'Content-Type':'application/json','X-ERP-Client':'web'}:{},body:body?JSON.stringify(body):undefined});if(!r.ok){const d=await r.json();throw new Error(d.detail||'下载失败')}const url=URL.createObjectURL(await r.blob());const a=document.createElement('a');a.href=url;a.download=decodeURIComponent(r.headers.get('Content-Disposition')?.match(/filename\*=UTF-8''(.+)/i)?.[1]||'')||name;a.click();setTimeout(()=>URL.revokeObjectURL(url),30000)}
async function template(row:any){try{await download(`/shipping/${row.id}/packing-template`,row.number+'-装箱单.xlsx')}catch(e){error.value=(e as Error).message}}
const uploadDialog=ref(false),uploadRow=ref<any>(null),uploadFile=ref<any>(null),uploadPreview=ref<any>(null),uploadError=ref('')
function openUpload(row:any){uploadRow.value=row;uploadFile.value=null;uploadPreview.value=null;uploadError.value='';uploadDialog.value=true}
async function pickFile(e:Event){uploadPreview.value=null;uploadError.value='';const f=(e.target as HTMLInputElement).files?.[0];if(!f)return;if(f.size>10000000){uploadError.value='文件不能超过10MB';return}busy.value=true;try{const data=await new Promise<string>((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(String(r.result).split(',')[1]);r.onerror=reject;r.readAsDataURL(f)});uploadFile.value={filename:f.name,content:data,revision:uploadRow.value.revision};uploadPreview.value=(await api(`/shipping/${uploadRow.value.id}/packing`,uploadFile.value)).preview}catch(e){uploadError.value=(e as Error).message}finally{busy.value=false}}
async function confirmUpload(){busy.value=true;uploadError.value='';try{await api(`/shipping/${uploadRow.value.id}/packing`,{...uploadFile.value,confirm:true});uploadDialog.value=false;ElMessage.success('装箱详情和原文件已保存');await load()}catch(e){uploadError.value=(e as Error).message}finally{busy.value=false}}
const detail=ref<any>(null),logRow=ref<any>(null),logRows=ref<any[]>([]),logPage=ref(1),logPageSize=ref(25),logTotal=ref(0),logBusy=ref(false),logError=ref('')
const logSteps:Record<string,string>={create:'创建入库计划',packing:'提交装箱',placement_options:'获取分仓方案',placement:'确认分仓',delivery_windows:'获取送达时段',transport_options:'获取承运人',transport:'确认配送服务',tracking:'提交追踪编码',rename:'重命名货件',cancel:'取消货件',refresh:'同步货件',retry:'重试步骤',prep_none:'提交预处理资料'}
const logStatuses:Record<string,string>={ready:'成功',completed:'已完成',failed:'失败',uncertain:'待核对',cancelled:'已取消'}
function logSummary(d:any){return [d.step&&(logSteps[d.step]||d.step),d.status&&(logStatuses[d.status]||d.status),d.filename,d.name,d.boxes!==undefined&&`${d.boxes} 箱`,d.quantity!==undefined&&`${d.quantity} 件`,d.packed!==undefined&&`装箱 ${d.packed} 件`,d.shipments?.join('、'),d.message].filter(Boolean).join(' · ')}
async function loadLogs(){logBusy.value=true;logError.value='';try{const d=await api(`/shipping/${logRow.value.id}/logs?page=${logPage.value}&page_size=${logPageSize.value}`);logRows.value=d.rows;logTotal.value=d.total}catch(e){logError.value=(e as Error).message}finally{logBusy.value=false}}
function showLogs(row:any){logRow.value=row;logPage.value=1;loadLogs()}
watch(()=>props.active,v=>{if(v)load()})
watch(()=>props.target,t=>{if(t)void showDetail({id:t.id})},{immediate:true})
async function showDetail(row:any){try{detail.value=await api(`/shipping/${row.id}/detail`)}catch(e){error.value=(e as Error).message}}
async function batchAction(action:string){if(busy.value)return;try{await ElMessageBox.confirm(action==='delete'?`删除选中的 ${selected.value.length} 个批次？将释放库存锁定，并恢复对应采购数量的可计划状态。`:'合并选中批次？需为同店铺、国家、渠道和仓库且未装箱；库存锁定与来源采购单会一起转移，计划发货日期取最晚日期。',action==='delete'?'批量删除':'合并批次',{type:'warning'});busy.value=true;await api('/shipping/batch',{action,tasks:selected.value.map(t=>({id:t.id,revision:t.revision}))});ElMessage.success(action==='delete'?'已删除并释放库存':'批次已合并');await load()}catch(e){if(e!=='cancel'&&e!=='close')error.value=(e as Error).message}finally{busy.value=false}}
const profileDialog=ref(false),profileEditor=ref(false),profileEditing=ref(false),profileLoading=ref(false),profileError=ref(''),profileRows=ref<any[]>([]),profile=reactive<any>({}),profileFields:Record<string,string>={representative_name:'英代 / 欧代联系人',representative_company:'英代 / 欧代名称',representative_email:'英代 / 欧代邮箱',representative_address:'英代 / 欧代地址',manufacturer_company:'制造商名称',manufacturer_email:'制造商邮箱',manufacturer_address:'制造商地址'}
async function loadProfiles(){profileLoading.value=true;try{profileRows.value=(await api('/shipping/profiles')).rows}catch(e){profileError.value=(e as Error).message}finally{profileLoading.value=false}}
async function openProfile(){profileError.value='';profileDialog.value=true;await loadProfiles()}
function editProfile(row?:any){profileError.value='';profileEditing.value=!!row;for(const k of Object.keys(profile))delete profile[k];Object.assign(profile,{store:row?.store||filters.store||options.stores[0],country:row?.country||'UK',revision:row?.revision||0,representative_expires:null,show_marks:true,...(row?.detail||{})});for(const k in profileFields)profile[k]??='';profileEditor.value=true}
async function saveProfile(){if(busy.value)return;busy.value=true;profileError.value='';try{await api('/shipping/profiles',profile);profileEditor.value=false;await loadProfiles();ElMessage.success('标签资料已保存')}catch(e){profileError.value=(e as Error).message}finally{busy.value=false}}
async function deleteProfile(row:any){try{await ElMessageBox.confirm(`删除 ${row.store} 的${row.country==='UK'?'英代':'欧代'}标签资料？`,'删除标签资料',{type:'warning'});await api('/shipping/profiles/remove-record',{store:row.store,country:row.country,revision:row.revision});await loadProfiles()}catch(e){if(e!=='cancel'&&e!=='close')profileError.value=(e as Error).message}}
const printRow=ref<any>(null),printMode=ref('plan'),printError=ref('')
function openPrint(row:any){printRow.value=row;printMode.value=row.packing_id?'packed':'plan';printError.value=''}
async function print(){busy.value=true;printError.value='';try{await download(`/shipping/${printRow.value.id}/labels`,printRow.value.number+'-50x50标签.pdf',{revision:printRow.value.revision,mode:printMode.value});printRow.value=null;await load()}catch(e){printError.value=(e as Error).message}finally{busy.value=false}}
onMounted(async()=>{try{Object.assign(options,await api('/shipping/options'));await load()}catch(e){error.value=(e as Error).message}});watch(()=>props.initialStore,v=>{filters.store=v;search()})
</script>
<template><div class="shipping-panel">
<div class="shipping-state-tabs"><el-radio-group v-model="filters.status" aria-label="发货计划状态" @change="search"><el-radio-button v-for="s in stateTabs" :key="s.key" :value="s.key">{{s.label}} ({{counts[s.key||'all']||0}})</el-radio-button></el-radio-group></div>

<el-alert v-if="error" :title="error" type="error" :closable="false"/>
<section class="shipping-list"><form class="shipping-filters" @submit.prevent="search"><el-input v-model="filters.q" placeholder="发货/采购单号 / 采购计划号 / SKU / 品名" clearable/><el-select v-model="filters.store" placeholder="全部店铺" clearable><el-option v-for="s in options.stores" :key="s" :value="s" :label="s"/></el-select><el-select v-model="filters.country" placeholder="全部国家" clearable><el-option v-for="(v,k) in options.countries" :key="k" :value="k" :label="String(v)"/></el-select><el-select v-model="filters.channel" placeholder="全部渠道" clearable><el-option v-for="(v,k) in options.channels" :key="k" :value="k" :label="String(v)"/></el-select><el-select v-model="filters.warehouse_id" placeholder="发货仓库" clearable><el-option v-for="w in options.warehouses" :key="w.id" :value="w.id" :label="w.name"/></el-select><el-button type="primary" native-type="submit">查询</el-button><el-dropdown v-if="admin" trigger="click" :disabled="!selected.length||busy||inventoryConfirming||loading" @command="selectedInventoryAction"><el-button class="inventory-menu-button" :disabled="!selected.length||busy||inventoryConfirming||loading" aria-label="库存">库存<span v-if="selected.length">（{{selected.length}}）</span><span aria-hidden="true"> ▾</span></el-button><template #dropdown><el-dropdown-menu><el-dropdown-item v-for="action in inventoryCommands" :key="action.key" :command="action.key" :disabled="inventoryBlocked(action.key)" :title="inventoryHint(action.key)">{{action.label}}</el-dropdown-item></el-dropdown-menu></template></el-dropdown><el-button v-if="admin" :disabled="selected.length<2||busy" @click="batchAction('merge')">合并批次</el-button><el-button v-if="admin" type="danger" plain :disabled="!selected.length||selected.some(t=>t.packing_id)||busy" @click="batchAction('delete')">批量删除</el-button><el-button @click="load">刷新列表</el-button><el-button v-if="admin" :disabled="busy" @click="planUploadOpen=true">上传发货计划</el-button><el-button v-if="admin" type="primary" @click="openEdit()">新增发货计划</el-button><TableReset table-key="ShippingPanel/table-1"/></form>
<template v-if="true"><el-table class="shipping-plan-table" border data-width-key="ShippingPanel/table-1" @header-dragend="(width: number, _old: number, column: any) => tableWidths.resize('table-1', width, column)" @header-contextmenu="(column: any, event: MouseEvent) => tableWidths.resetColumn('table-1', column, event)" :data="rows" v-loading="loading" row-key="id" @selection-change="(v:any[])=>selected=v" empty-text="暂无发货计划。请从采购单选择生成批次，或手动新增。">
<el-table-column :column-key="'column-1'" v-if="admin" type="selection" :width="tableWidths.width('table-1', 'column-1', '45')"/>
<el-table-column :column-key="'column-2'" :width="tableWidths.width('table-1', 'column-2', undefined)" type="expand"><template #default="{row}"><div class="shipping-detail-wrap nested-detail"><template v-if="true"><el-table border data-width-key="ShippingPanel/detail-items" :data="row.items" class="shipping-detail-table" @header-dragend="(width:number,_old:number,column:any)=>tableWidths.resize('detail-items',width,column)" @header-contextmenu="(column:any,event:MouseEvent)=>tableWidths.resetColumn('detail-items',column,event)">
<el-table-column column-key="image" label="图片" :width="tableWidths.width('detail-items','image',75)"><template #default="{row:i}"><img v-if="i.image_url" :src="i.image_url" class="shipping-detail-image"/><span v-else>—</span></template></el-table-column>
<el-table-column column-key="product" label="标品编码 / 品名" min-width="240" :width="tableWidths.width('detail-items','product',undefined)"><template #default="{row:i}"><b>{{i.code}}</b><div>{{i.name}}</div></template></el-table-column>
<el-table-column column-key="sku" label="SKU / FNSKU" min-width="260" :width="tableWidths.width('detail-items','sku',undefined)"><template #default="{row:i}"><div>{{i.sku||'待选择店铺 SKU'}}</div><small>{{i.fnsku||'FNSKU待补齐'}}</small></template></el-table-column>
<el-table-column column-key="quantity" prop="quantity" label="计划发货量" align="center" :width="tableWidths.width('detail-items','quantity',175)"><template #default="{row}"><span class="planned-quantity"><span>{{row.quantity}}</span><small v-if="hasOriginalPlan(row)" class="original-plan">原计划: {{row.original_quantity}}</small></span></template></el-table-column>
<el-table-column column-key="packed" prop="packed" label="已装箱量" align="center" :width="tableWidths.width('detail-items','packed',100)"/>
<el-table-column column-key="difference" label="总计划差额" align="center" :width="tableWidths.width('detail-items','difference',130)"><template #default="{row:i}"><span class="plan-difference" :class="{'positive':i.total_plan_difference>0,'negative':i.total_plan_difference<0}" :title="`仓库可用量 ${i.warehouse_available??'—'} − 未完成计划总量 ${i.total_planned_quantity??'—'}`">{{i.total_plan_difference??'—'}}</span></template></el-table-column>
<el-table-column v-if="admin" column-key="actions" label="操作" fixed="right" :width="tableWidths.width('detail-items','actions',145)"><template #default="{row:i,$index}"><span :title="itemHint(row)"><el-button link type="primary" :disabled="busy||itemBlocked(row)" @click="editItem(row,i,$index)">编辑</el-button></span><span :title="itemHint(row)||(i.packed?'请先在装箱单中移除该商品':'')"><el-button link type="danger" :disabled="busy||itemBlocked(row)||i.packed>0" @click="deleteItem(row,i,$index)">删除</el-button></span></template></el-table-column>
</el-table></template></div></template></el-table-column>
<el-table-column :column-key="'column-3'" label="批次编号" :width="tableWidths.width('table-1', 'column-3', '155')"><template #default="{row}"><el-button link type="primary" @click="showDetail(row)">{{row.number}}</el-button><div class="shipping-source"><span class="source-number" :title="sourceNumbers(row)[0]">{{sourceNumbers(row)[0]||(row.source==='receipt'?'历史到货生成':row.source==='purchase_plan'?'采购计划':row.source==='purchase'?'采购单':'手动新增')}}</span><el-popover v-if="sourceNumbers(row).length>1" trigger="click" placement="bottom-start" :width="220"><template #reference><button class="source-more" :aria-label="`展开 ${row.number} 的其他来源批次号`" @click.stop>▾</button></template><div class="source-list"><div v-for="code in sourceNumbers(row).slice(1)" :key="code">{{code}}</div></div></el-popover></div></template></el-table-column>
<el-table-column :column-key="'column-4'" label="状态" :width="tableWidths.width('table-1', 'column-4', '130')"><template #default="{row}"><el-tag :type="row.status==='packed'?'success':'info'">{{stateLabel[row.workflow_status]||options.states[row.status]}}</el-tag><small v-if="row.missing_sku" class="risk-text">{{row.missing_sku}}项SKU待确认</small></template></el-table-column>
<el-table-column :column-key="'store'" prop="store" label="店铺" :width="tableWidths.width('table-1', 'store', '110')"/><el-table-column :column-key="'column-6'" label="国家 / 渠道" :width="tableWidths.width('table-1', 'column-6', '120')"><template #default="{row}">{{options.countries[row.country]}} · {{options.channels[row.channel]}}</template></el-table-column>
<el-table-column column-key="inventory-status" label="库存状态" :width="tableWidths.width('table-1','inventory-status',170)"><template #default="{row}"><span class="inventory-inline"><el-tag :type="row.inventory_status==='outbound'?'success':row.inventory_status==='locked'?'warning':'info'">{{inventoryLabel[row.inventory_status]||'未锁定'}}</el-tag><span v-if="row.inventory_status==='locked'" class="inventory-count">{{row.locked}} 件</span></span></template></el-table-column>
<el-table-column :column-key="'column-8'" :width="tableWidths.width('table-1', 'column-8', undefined)" label="产品信息" min-width="210"><template #default="{row}"><div class="shipping-thumb"><img v-for="(i,n) in row.items.slice(0,3)" :key="n" :src="i.image_url||undefined" :alt="i.code"/><span>{{row.items.length}}款</span></div></template></el-table-column>
<el-table-column :column-key="'quantity'" prop="quantity" label="计划数量" :width="tableWidths.width('table-1', 'quantity', '175')" align="center"><template #default="{row}"><span class="planned-quantity"><span>{{row.quantity}}</span><small v-if="hasOriginalPlan(row)" class="original-plan">原计划: {{row.original_quantity}}</small></span></template></el-table-column><el-table-column :column-key="'column-10'" label="已装箱数量" :width="tableWidths.width('table-1', 'column-10', '140')" align="center"><template #default="{row}"><span class="packed-inline">{{row.packed}} / {{row.boxes}} 箱</span></template></el-table-column>
<el-table-column :column-key="'warehouse_name'" prop="warehouse_name" label="发货仓库" :width="tableWidths.width('table-1', 'warehouse_name', '125')"/><el-table-column :column-key="'actor'" prop="actor" label="创建人" :width="tableWidths.width('table-1', 'actor', '100')"/><el-table-column :column-key="'column-13'" label="创建时间" :width="tableWidths.width('table-1', 'column-13', '155')"><template #default="{row}">{{stamp(row.created_at)}}</template></el-table-column><el-table-column :column-key="'ship_date'" prop="ship_date" label="计划发货日期" :width="tableWidths.width('table-1', 'ship_date', '130')"/>

<el-table-column :column-key="'column-17'" label="FBA 货件号" :width="tableWidths.width('table-1', 'column-17', '185')"><template #default="{row}"><template v-if="row.sta?.fba_ids?.length"><el-button v-for="id in row.sta.fba_ids" :key="id" link type="primary" @click="emit('open-sta',{shippingId:row.id,taskId:row.sta.id})">{{id}}</el-button></template><el-button v-else-if="row.sta" link type="primary" @click="emit('open-sta',{shippingId:row.id,taskId:row.sta.id})">货件创建中</el-button><span v-else>未创建</span></template></el-table-column><el-table-column :column-key="'column-18'" label="操作" :width="tableWidths.width('table-1', 'column-18', '285')" fixed="right"><template #default="{row}"><div class="shipping-actions">
<el-button class="action-print" link :disabled="busy" @click="openPrint(row)">打印标签</el-button>
<el-button class="action-packing" link :disabled="busy" @click="template(row)">下载装箱单</el-button>
<el-button v-if="admin" class="action-packing" link :disabled="!!row.packing_id||!!row.sta||!!row.outbound_at||busy" @click="openUpload(row)">上传装箱单</el-button>
<el-button v-if="admin" class="action-packing" link :disabled="!row.packing_id||!!row.sta||!!row.outbound_at||busy" @click="editPacking(row)">编辑装箱单</el-button>
<el-button v-if="admin" class="action-shipment" link :disabled="!row.packing_id||busy" @click="emit('open-sta',{shippingId:row.id,taskId:row.sta?.id})">{{row.sta?'查看货件':'做货件'}}</el-button>
<el-button v-if="admin" class="action-shipment" link :disabled="!row.outbound_at||row.remainder_created||!row.packing_id||!row.remaining||busy" @click="inventoryAction(row,'remainder')">创建剩货计划</el-button>
<el-button v-if="admin" class="action-edit" link :disabled="!!row.packing_id||!!row.sta||!!row.outbound_at||busy" @click="openEdit(row)">编辑</el-button>
<el-button v-if="admin" class="action-delete" link :disabled="!!row.packing_id||!!row.outbound_at||!!row.sta||busy" @click="remove(row)">删除</el-button>
<el-button class="action-log" link :disabled="busy" @click="showLogs(row)">日志</el-button>
</div></template></el-table-column></el-table></template>
<AppPagination v-model:current-page="page" :total="total" @change="load" v-model:page-size="pageSize"/>
</section>
<ShippingPlanUpload v-if="planUploadOpen" :options="options" :initial="filters" @close="planUploadOpen=false" @saved="planUploadOpen=false;load()"/>
<ShippingPackingEditor v-if="packingEdit" :plan="packingEdit" @close="packingEdit=null" @saved="packingEdit=null;load()"/>
<el-dialog :model-value="!!logRow" @close="logRow=null" title="发货计划操作日志" width="min(1080px,96vw)"><template v-if="logRow"><h3>{{logRow.title}} · {{logRow.number}}</h3><el-alert v-if="logError" :title="logError" type="error" :closable="false"/><template v-if="true"><TableReset table-key="ShippingPanel/table-2"/><el-table border data-width-key="ShippingPanel/table-2" @header-dragend="(width: number, _old: number, column: any) => tableWidths.resize('table-2', width, column)" @header-contextmenu="(column: any, event: MouseEvent) => tableWidths.resetColumn('table-2', column, event)" :data="logRows" v-loading="logBusy" empty-text="暂无操作日志"><el-table-column :column-key="'column-1'" label="操作时间" :width="tableWidths.width('table-2', 'column-1', '180')"><template #default="{row}">{{stamp(row.created_at)}}</template></el-table-column><el-table-column :column-key="'actor'" prop="actor" label="操作人" :width="tableWidths.width('table-2', 'actor', '120')"/><el-table-column :column-key="'title'" prop="title" label="操作" :width="tableWidths.width('table-2', 'title', '170')"/><el-table-column :column-key="'column-4'" :width="tableWidths.width('table-2', 'column-4', undefined)" label="详情"><template #default="{row}">{{logSummary(row.detail)}}</template></el-table-column></el-table></template><AppPagination v-model:current-page="logPage" :total="logTotal" @change="loadLogs" v-model:page-size="logPageSize"/></template></el-dialog>
<el-dialog v-model="itemEditor" title="编辑计划数量" width="440px" :close-on-click-modal="false"><el-alert v-if="itemError" :title="itemError" type="error" :closable="false"/><p>{{itemForm.code}} · {{itemForm.name}}</p><el-form label-position="top"><el-form-item label="计划发货量"><el-input-number v-model="itemForm.quantity" :min="itemForm.minimum" :max="100000" :precision="0" :disabled="busy" aria-label="明细计划数量"/></el-form-item></el-form><p v-if="itemForm.minimum>1">不能低于已装箱量 {{itemForm.minimum}} 件。</p><template #footer><el-button :disabled="busy" @click="itemEditor=false">取消</el-button><el-button type="primary" :loading="busy" @click="saveItem">保存</el-button></template></el-dialog>
<el-dialog v-model="editor" :title="editId?'编辑发货计划':'新增发货计划'" width="min(1100px,96vw)" :close-on-click-modal="false"><el-alert v-if="dialogError" :title="dialogError" type="error" :closable="false"/><el-form label-position="top" :disabled="busy"><el-form-item v-if="!editId" label="是否锁定库存"><el-radio-group v-model="form.lock_inventory" @change="dialogError=''"><el-radio :value="false">否，不锁定库存</el-radio><el-radio :value="true">是，校验并锁定库存</el-radio></el-radio-group></el-form-item><div class="shipping-grid"><el-form-item label="店铺"><el-select v-model="form.store" :disabled="form.from_purchase" @change="destinations"><el-option v-for="s in options.stores" :key="s" :value="s" :label="s"/></el-select></el-form-item><el-form-item label="国家"><el-select v-model="form.country" :disabled="form.from_purchase" @change="destinations"><el-option v-for="(v,k) in options.countries" :key="k" :value="k" :label="String(v)"/></el-select></el-form-item><el-form-item label="渠道"><el-select v-model="form.channel" :disabled="form.from_purchase"><el-option v-for="(v,k) in options.channels" :key="k" :value="k" :label="String(v)"/></el-select></el-form-item><el-form-item label="发货仓库"><el-select v-model="form.warehouse_id" :disabled="form.from_purchase"><el-option v-for="w in options.warehouses" :key="w.id" :value="w.id" :label="w.name"/></el-select></el-form-item><el-form-item label="计划发货日期"><el-date-picker v-model="form.ship_date" value-format="YYYY-MM-DD"/></el-form-item></div>
<p v-if="form.from_purchase">采购来源批次可新增商品，调整计划发货量、SKU、发货日期和备注。</p><el-button v-if="editId" @click="addingProducts=!addingProducts">{{addingProducts?'收起产品列表':'新增商品'}}</el-button><ShippingProductPicker v-if="editor&&(!editId||addingProducts)" v-model="form.items" :store="form.store" :country="form.country" :protected-ids="form.from_purchase?originalProducts:[]" :disabled="busy" @busy="pickerBusy=$event"/>
<template v-if="editId"><TableReset table-key="ShippingPanel/table-3"/><el-table  border data-width-key="ShippingPanel/table-3" @header-dragend="(width: number, _old: number, column: any) => tableWidths.resize('table-3', width, column)" @header-contextmenu="(column: any, event: MouseEvent) => tableWidths.resetColumn('table-3', column, event)" :data="form.items"><el-table-column :column-key="'column-1'" :width="tableWidths.width('table-3', 'column-1', undefined)" label="标品 / 品名" min-width="230"><template #default="{row}">{{row.code}}<small>{{row.name}}</small></template></el-table-column><el-table-column :column-key="'column-2'" :width="tableWidths.width('table-3', 'column-2', undefined)" label="店铺 SKU / FNSKU" min-width="340"><template #default="{row}"><el-select v-model="row.listing_id" placeholder="选择匹配 SKU；没有记录请先关联Listing" clearable><el-option v-for="l in row.candidates" :key="l.id" :value="l.id" :label="l.sku+' · '+(l.fnsku||'FNSKU未返回')"/></el-select></template></el-table-column><el-table-column :column-key="'column-3'" label="发货数量" :width="tableWidths.width('table-3', 'column-3', '170')" align="center"><template #default="{row}"><el-input-number v-model="row.quantity" :min="1" :max="100000" :precision="0"/></template></el-table-column><el-table-column :column-key="'column-4'" :width="tableWidths.width('table-3', 'column-4', '70')"><template #default="{$index}"><el-button link type="danger" :disabled="form.from_purchase&&originalProducts.includes(form.items[$index].product_id)" @click="form.items.splice($index,1)">移除</el-button></template></el-table-column></el-table></template><el-form-item label="备注"><el-input v-model="form.note" maxlength="1000"/></el-form-item><el-checkbox v-if="form.packing_id" v-model="form.discard_packing">确认变更后重新装箱，原装箱文件保留在历史记录中</el-checkbox></el-form><template #footer><el-button :disabled="busy" @click="editor=false">取消</el-button><el-button type="primary" :loading="busy" :disabled="pickerBusy" @click="save">保存</el-button></template></el-dialog>
<el-dialog v-model="uploadDialog" title="上传装箱单" width="min(1000px,95vw)" :close-on-click-modal="false"><p>支持空白模板填写后的格式及领星装箱格式。可加入当前计划外的 SKU，须已关联当前店铺、国家的标品；确认后将自动补入发货计划并记录日志。请填写每箱数量、重量（kg）和长宽高（cm）。再次上传会替换当前装箱结果，原文件仍保留。</p><input type="file" accept=".xlsx" :disabled="busy" @change="pickFile"/><el-alert v-if="uploadError" :title="uploadError" type="error" :closable="false"/><template v-if="uploadPreview"><el-alert v-if="uploadPreview.plan_additions?.length" :title="`将通过装箱单新增 ${uploadPreview.plan_additions.length} 个 SKU 到发货计划`" type="info" :closable="false"/><h3>{{uploadPreview.boxes.length}}箱 · 已装箱 {{uploadPreview.packed}}件 · 待装 {{uploadPreview.remaining}}件</h3><template v-if="true"><TableReset table-key="ShippingPanel/table-4"/><el-table border data-width-key="ShippingPanel/table-4" @header-dragend="(width: number, _old: number, column: any) => tableWidths.resize('table-4', width, column)" @header-contextmenu="(column: any, event: MouseEvent) => tableWidths.resetColumn('table-4', column, event)" :data="uploadPreview.items"><el-table-column :column-key="'sku'" :width="tableWidths.width('table-4', 'sku', undefined)" prop="sku" label="SKU"/><el-table-column :column-key="'fnsku'" :width="tableWidths.width('table-4', 'fnsku', undefined)" prop="fnsku" label="FNSKU"/><el-table-column :column-key="'quantity'" :width="tableWidths.width('table-4', 'quantity', undefined)" prop="quantity" label="计划数量" align="center"><template #default="{row}"><span class="planned-quantity"><span>{{row.quantity}}</span><small v-if="hasOriginalPlan(row)" class="original-plan">原计划: {{row.original_quantity}}</small></span></template></el-table-column><el-table-column :column-key="'packed'" :width="tableWidths.width('table-4', 'packed', undefined)" prop="packed" label="已装箱"/><el-table-column :column-key="'remaining'" :width="tableWidths.width('table-4', 'remaining', undefined)" prop="remaining" label="待装"/></el-table></template></template><template #footer><el-button :disabled="busy" @click="uploadDialog=false">取消</el-button><el-button type="primary" :disabled="!uploadPreview" :loading="busy" @click="confirmUpload">确认保存装箱详情</el-button></template></el-dialog>
<el-dialog :model-value="!!detail" @close="detail=null" title="发货与装箱详情" width="min(1100px,95vw)"><template v-if="detail"><h3>{{detail.number}} · {{detail.title}}</h3><p>{{detail.note}}</p><template v-if="true"><TableReset table-key="ShippingPanel/table-5"/><el-table border data-width-key="ShippingPanel/table-5" @header-dragend="(width: number, _old: number, column: any) => tableWidths.resize('table-5', width, column)" @header-contextmenu="(column: any, event: MouseEvent) => tableWidths.resetColumn('table-5', column, event)" :data="detail.items"><el-table-column :column-key="'sku'" :width="tableWidths.width('table-5', 'sku', undefined)" prop="sku" label="SKU"/><el-table-column :column-key="'name'" :width="tableWidths.width('table-5', 'name', undefined)" prop="name" label="品名"/><el-table-column :column-key="'fnsku'" :width="tableWidths.width('table-5', 'fnsku', undefined)" prop="fnsku" label="FNSKU"/><el-table-column :column-key="'quantity'" prop="quantity" label="发货数量" :width="tableWidths.width('table-5', 'quantity', '110')" align="center"><template #default="{row}"><span class="planned-quantity"><span>{{row.quantity}}</span><small v-if="hasOriginalPlan(row)" class="original-plan">原计划: {{row.original_quantity}}</small></span></template></el-table-column></el-table></template><h4>装箱明细</h4><div v-if="detail.packing"><div v-for="b in detail.packing.boxes" :key="b.number" class="shipping-box"><b>第{{b.number}}箱 · {{b.quantity}}件 · {{b.weight_kg}}kg · {{b.length_cm}}×{{b.width_cm}}×{{b.height_cm}}cm</b><div v-for="i in b.items" :key="i.sku">{{i.sku}} · {{i.fnsku}} · {{i.quantity}}件</div></div></div><el-empty v-else description="尚无装箱数据"/><h4>装箱文件历史</h4><p v-for="f in detail.packing_history" :key="f.id"><el-button link type="primary" @click="download(`/shipping/${detail.id}/packing/${f.id}`,f.filename).catch(e=>error=e.message)">{{f.filename}}</el-button> {{f.actor}} · {{stamp(f.created_at)}}</p></template></el-dialog>
<el-dialog v-model="profileDialog" title="店铺标签资料" width="min(1200px,96vw)" :close-on-click-modal="false"><p>英代用于英国；欧代用于欧洲各国。同一店铺分别维护一份，打印时自动选择。</p><el-alert v-if="profileError&&!profileEditor" :title="profileError" type="error" :closable="false"/><el-button type="primary" @click="editProfile()">新增标签资料</el-button><template v-if="true"><TableReset table-key="ShippingPanel/table-6"/><el-table border data-width-key="ShippingPanel/table-6" @header-dragend="(width: number, _old: number, column: any) => tableWidths.resize('table-6', width, column)" @header-contextmenu="(column: any, event: MouseEvent) => tableWidths.resetColumn('table-6', column, event)" :data="profileRows" v-loading="profileLoading"><el-table-column :column-key="'store'" prop="store" label="店铺" :width="tableWidths.width('table-6', 'store', '120')"/><el-table-column :column-key="'column-2'" label="代理类型" :width="tableWidths.width('table-6', 'column-2', '100')"><template #default="{row}">{{row.country==='UK'?'英代':'欧代'}}</template></el-table-column><el-table-column :column-key="'detail.representative_company'" :width="tableWidths.width('table-6', 'detail.representative_company', undefined)" prop="detail.representative_company" label="代理公司" min-width="190"/><el-table-column :column-key="'detail.manufacturer_company'" :width="tableWidths.width('table-6', 'detail.manufacturer_company', undefined)" prop="detail.manufacturer_company" label="制造商" min-width="190"/><el-table-column :column-key="'column-5'" :width="tableWidths.width('table-6', 'column-5', undefined)" label="资料检查" min-width="220"><template #default="{row}"><el-tag v-if="!row.missing.length" type="success">完整</el-tag><span v-else class="risk-text">缺少：{{row.missing.join('、')}}</span></template></el-table-column><el-table-column :column-key="'column-6'" label="操作" :width="tableWidths.width('table-6', 'column-6', '130')"><template #default="{row}"><el-button link type="primary" @click="editProfile(row)">修改</el-button><el-button link type="danger" @click="d